import os
from typing import Any

import requests
from langflow.custom import Component
from langflow.io import MessageTextInput, Output, SecretStrInput
from langflow.schema import Data


class PolicyRAGAgentTool(Component):
    display_name = "Policy RAG Agent"

    description = """
    Use this tool exactly once for company-policy questions concerning:

    - returns
    - refunds
    - exchanges
    - cancellations
    - return eligibility
    - return time limits
    - product and footwear fit
    - shipping and delivery policy
    - delivered-but-missing policy guidance
    - account-security policy guidance
    - VIP treatment
    - other approved company rules

    Pass the customer's complete policy question and all relevant
    current-session context.

    Do not use this tool for:
    - greetings
    - live order or shipment status
    - carrier tracking
    - retrieving operational order information
    - creating human escalations
    - unauthorized-access incidents requiring immediate action
    - suspected fraud requiring immediate action

    Never answer company-specific policy from general model knowledge.
    Use the retrieved response returned by this specialist.
    
    Pass only the company-policy part of the request and the context required
    to understand that policy question.
    
    For mixed requests, exclude live order-status instructions from this
    tool's query.
    """

    icon = "BookOpenCheck"
    name = "PolicyRAGAgentTool"

    inputs = [
        MessageTextInput(
            name="query",
            display_name="Policy Query",
            info=(
                "The customer's complete company-policy question, "
                "including relevant current-session context."
            ),
            tool_mode=True,
            required=True,
        ),
        SecretStrInput(
            name="langflow_api_key",
            display_name="Langflow API Key",
            info=(
                "Langflow API key used to call the Policy RAG child flow. "
                "Bind this field to the secure LANGFLOW_API_KEY "
                "Global Variable."
            ),
            required=True,
            advanced=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Agent Result",
            name="result",
            method="run_policy_rag_agent",
        )
    ]

    def _get_api_key(self) -> str:
        """
        Retrieve the real API-key value.

        Langflow credential fields may return a protected SecretStr object.
        Calling str() directly on that object can return masked characters,
        so get_secret_value() must be used when available.
        """
        raw_api_key = self.langflow_api_key

        if hasattr(raw_api_key, "get_secret_value"):
            secret_value = raw_api_key.get_secret_value()
            return secret_value.strip() if secret_value else ""

        if raw_api_key:
            return str(raw_api_key).strip()

        return os.getenv(
            "LANGFLOW_API_KEY",
            "",
        ).strip()

    def _extract_text(self, payload: Any) -> str:
        """Extract the final AI response text from a Langflow API result."""
        candidates: list[str] = []

        def visit(value: Any) -> None:
            if isinstance(value, dict):
                # These fields commonly contain Langflow output text.
                for key in (
                    "text",
                    "message",
                    "output",
                    "result",
                    "response",
                ):
                    item = value.get(key)

                    if isinstance(item, str) and item.strip():
                        candidates.append(item.strip())

                # Recursively inspect nested Langflow result structures.
                for item in value.values():
                    visit(item)

            elif isinstance(value, list):
                for item in value:
                    visit(item)

        visit(payload)

        return candidates[-1] if candidates else ""

    def run_policy_rag_agent(self) -> Data:
        """Validate the policy query and execute the Policy RAG child flow."""
        query = (self.query or "").strip()

        # ---------------------------------------------------------
        # 1. Validate the query
        # ---------------------------------------------------------
        if not query:
            return Data(
                data={
                    "success": True,
                    "completed": False,
                    "status": "clarification_required",
                    "response": (
                        "Please provide the company-policy question "
                        "you would like me to check."
                    ),
                }
            )

        # ---------------------------------------------------------
        # 2. Retrieve and validate the Langflow API key
        # ---------------------------------------------------------
        langflow_api_key = self._get_api_key()

        if not langflow_api_key:
            return Data(
                data={
                    "success": False,
                    "completed": False,
                    "status": "configuration_error",
                    "error": "missing_langflow_api_key",
                    "response": (
                        "The Langflow API key is not configured for "
                        "the Policy RAG Agent component."
                    ),
                }
            )

        # ---------------------------------------------------------
        # 3. Prepare the Policy RAG child-flow request
        # ---------------------------------------------------------
        base_url = os.getenv(
            "LANGFLOW_BASE_URL",
            "http://127.0.0.1:7860",
        ).strip().rstrip("/")

        policy_rag_flow_id = (
            "c2f83c08-2487-4b0e-a3d0-3daba104f41a"
        )

        endpoint = (
            f"{base_url}/api/v1/run/{policy_rag_flow_id}"
        )

        headers = {
            "Content-Type": "application/json",
            "x-api-key": langflow_api_key,
        }

        request_body = {
            "input_value": query,
            "input_type": "chat",
            "output_type": "chat",
        }

        # ---------------------------------------------------------
        # 4. Execute the Policy RAG child flow
        # ---------------------------------------------------------
        try:
            response = requests.post(
                endpoint,
                headers=headers,
                json=request_body,
                timeout=120,
            )

            response.raise_for_status()

        except requests.Timeout:
            return Data(
                data={
                    "success": False,
                    "completed": False,
                    "status": "failed",
                    "error": "policy_rag_timeout",
                    "response": (
                        "The policy retrieval service timed out. "
                        "Please try again shortly."
                    ),
                }
            )

        except requests.HTTPError as exc:
            status_code = (
                exc.response.status_code
                if exc.response is not None
                else None
            )

            server_detail = ""

            if exc.response is not None:
                try:
                    server_detail = exc.response.text[:500]
                except Exception:
                    server_detail = ""

            return Data(
                data={
                    "success": False,
                    "completed": False,
                    "status": "failed",
                    "error": "policy_rag_http_error",
                    "status_code": status_code,
                    "api_key_configured": bool(langflow_api_key),
                    "response": (
                        "The policy retrieval service could not "
                        "complete the request."
                    ),
                    "server_detail": server_detail,
                    "detail": str(exc)[:500],
                }
            )

        except requests.RequestException as exc:
            return Data(
                data={
                    "success": False,
                    "completed": False,
                    "status": "failed",
                    "error": "policy_rag_connection_failed",
                    "response": (
                        "The policy retrieval service is currently "
                        "unavailable."
                    ),
                    "detail": str(exc)[:500],
                }
            )

        # ---------------------------------------------------------
        # 5. Parse the child-flow response
        # ---------------------------------------------------------
        try:
            payload = response.json()

        except ValueError as exc:
            return Data(
                data={
                    "success": False,
                    "completed": False,
                    "status": "failed",
                    "error": "invalid_policy_rag_response",
                    "response": (
                        "The policy retrieval service returned an "
                        "invalid response."
                    ),
                    "detail": str(exc)[:500],
                }
            )

        answer = self._extract_text(payload)

        if not answer:
            return Data(
                data={
                    "success": False,
                    "completed": False,
                    "status": "failed",
                    "error": "empty_policy_rag_response",
                    "response": (
                        "No approved policy information was returned "
                        "for this question."
                    ),
                }
            )

        # ---------------------------------------------------------
        # 6. Return the successful specialist result
        # ---------------------------------------------------------
        return Data(
            data={
                "success": True,
                "completed": True,
                "status": "completed",
                "agent": "policy_rag",
                "response": answer,
            }
        )
